gsap-sel:fade:
import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

export function useFadeAnimation(containerRef: React.RefObject<HTMLElement>) {
  useGSAP(() => {
    // GSAP 3.12 Production Timeline Driver
    // Target: .card | Duration: 800ms | Easing: power2.out
    const tl = gsap.timeline({ scrollTrigger: { trigger: ".card", start: "top 80%", end: "bottom 20%", scrub: true, pin: true, markers: true } });
    tl.to(".card", { opacity: 1, y: 2, duration: 0.400, ease: "power2.out" });
    tl.to(".card", { opacity: "20px", y: 3, duration: 0.400, ease: "power2.out" });
  }, { scope: containerRef });
}

